-- Vier pakketten per dienstsoort: Informatieve Websites, Webshops, Marketing SEO, Linkbuilding, Social Media Onderhoud.
SET @fc_n = (SELECT COALESCE(MAX(CAST(SUBSTRING(Nummer, 2) AS UNSIGNED)), 0) FROM Producten WHERE Nummer REGEXP '^A[0-9]+$');
INSERT INTO Producten (Nummer, Groep, Dienstsoort, Naam, Slug, Omschrijving, Kenmerken, Prijs, Periode, Instelkosten, BtwTarief, Uitgelicht, Zichtbaar, Volgorde, AangemaaktOp)
SELECT CONCAT('A', LPAD(@fc_n := @fc_n + 1, 5, '0')), t.Groep, t.Dienstsoort, t.Naam, t.Slug, t.Omschrijving, t.Kenmerken, t.Prijs, t.Periode, 0, 21.00, t.Uitgelicht, 1, t.Volgorde, NOW()
FROM (
SELECT 'Websites' AS Groep, 'Informatieve Websites' AS Dienstsoort, 'Website Start' AS Naam, 'website-start' AS Slug, 'Informatieve Websites-pakket Start.' AS Omschrijving, '["1 pagina (onepager)", "Responsive design", "Contactformulier", "SSL-certificaat", "Oplevering binnen 1 week"]' AS Kenmerken, 49500 AS Prijs, 'eenmalig' AS Periode, 0 AS Uitgelicht, 1 AS Volgorde
UNION ALL SELECT 'Websites' AS Groep, 'Informatieve Websites' AS Dienstsoort, 'Website Basis' AS Naam, 'website-basis' AS Slug, 'Informatieve Websites-pakket Basis.' AS Omschrijving, '["Tot 5 pagina''s", "Responsive design", "CMS om zelf te beheren", "Basis-SEO", "Oplevering binnen 2 weken"]' AS Kenmerken, 89500 AS Prijs, 'eenmalig' AS Periode, 1 AS Uitgelicht, 2 AS Volgorde
UNION ALL SELECT 'Websites' AS Groep, 'Informatieve Websites' AS Dienstsoort, 'Website Pro' AS Naam, 'website-pro' AS Slug, 'Informatieve Websites-pakket Pro.' AS Omschrijving, '["Tot 10 pagina''s", "Uniek ontwerp in jouw huisstijl", "CMS en blog", "SEO-optimalisatie", "Google Analytics-koppeling"]' AS Kenmerken, 149500 AS Prijs, 'eenmalig' AS Periode, 0 AS Uitgelicht, 3 AS Volgorde
UNION ALL SELECT 'Websites' AS Groep, 'Informatieve Websites' AS Dienstsoort, 'Website Premium' AS Naam, 'website-premium' AS Slug, 'Informatieve Websites-pakket Premium.' AS Omschrijving, '["Onbeperkt pagina''s", "Maatwerk ontwerp en animaties", "Meertalig", "Uitgebreide SEO", "Persoonlijke training"]' AS Kenmerken, 249500 AS Prijs, 'eenmalig' AS Periode, 0 AS Uitgelicht, 4 AS Volgorde
UNION ALL SELECT 'Websites' AS Groep, 'Webshops' AS Dienstsoort, 'Webshop Start' AS Naam, 'webshop-start' AS Slug, 'Webshops-pakket Start.' AS Omschrijving, '["Tot 25 producten", "iDEAL en creditcard", "Responsive design", "Voorraadbeheer", "SSL-certificaat"]' AS Kenmerken, 99500 AS Prijs, 'eenmalig' AS Periode, 0 AS Uitgelicht, 1 AS Volgorde
UNION ALL SELECT 'Websites' AS Groep, 'Webshops' AS Dienstsoort, 'Webshop Basis' AS Naam, 'webshop-basis' AS Slug, 'Webshops-pakket Basis.' AS Omschrijving, '["Tot 250 producten", "Mollie-betalingen", "Kortingscodes", "Verzendmodule (PostNL/DHL)", "Basis-SEO"]' AS Kenmerken, 179500 AS Prijs, 'eenmalig' AS Periode, 1 AS Uitgelicht, 2 AS Volgorde
UNION ALL SELECT 'Websites' AS Groep, 'Webshops' AS Dienstsoort, 'Webshop Pro' AS Naam, 'webshop-pro' AS Slug, 'Webshops-pakket Pro.' AS Omschrijving, '["Onbeperkt producten", "Koppeling met boekhouding", "Klantaccounts en favorieten", "SEO-optimalisatie", "Productfilters"]' AS Kenmerken, 299500 AS Prijs, 'eenmalig' AS Periode, 0 AS Uitgelicht, 3 AS Volgorde
UNION ALL SELECT 'Websites' AS Groep, 'Webshops' AS Dienstsoort, 'Webshop Premium' AS Naam, 'webshop-premium' AS Slug, 'Webshops-pakket Premium.' AS Omschrijving, '["Maatwerk ontwerp", "Koppelingen met ERP/voorraad", "Meertalig en meerdere valuta", "B2B-prijzen", "Persoonlijke training"]' AS Kenmerken, 499500 AS Prijs, 'eenmalig' AS Periode, 0 AS Uitgelicht, 4 AS Volgorde
UNION ALL SELECT 'Overig' AS Groep, 'Marketing SEO' AS Dienstsoort, 'SEO Start' AS Naam, 'seo-start' AS Slug, 'Marketing SEO-pakket Start.' AS Omschrijving, '["Zoekwoordenonderzoek (10 woorden)", "Technische SEO-check", "Maandelijks rapport"]' AS Kenmerken, 19500 AS Prijs, 'maand' AS Periode, 0 AS Uitgelicht, 1 AS Volgorde
UNION ALL SELECT 'Overig' AS Groep, 'Marketing SEO' AS Dienstsoort, 'SEO Groei' AS Naam, 'seo-groei' AS Slug, 'Marketing SEO-pakket Groei.' AS Omschrijving, '["25 zoekwoorden", "On-page optimalisatie", "Google Bedrijfsprofiel", "Maandelijks rapport"]' AS Kenmerken, 39500 AS Prijs, 'maand' AS Periode, 1 AS Uitgelicht, 2 AS Volgorde
UNION ALL SELECT 'Overig' AS Groep, 'Marketing SEO' AS Dienstsoort, 'SEO Pro' AS Naam, 'seo-pro' AS Slug, 'Marketing SEO-pakket Pro.' AS Omschrijving, '["50 zoekwoorden", "Contentplan en 2 blogs per maand", "Concurrentieanalyse", "Maandelijks overleg"]' AS Kenmerken, 69500 AS Prijs, 'maand' AS Periode, 0 AS Uitgelicht, 3 AS Volgorde
UNION ALL SELECT 'Overig' AS Groep, 'Marketing SEO' AS Dienstsoort, 'SEO Premium' AS Naam, 'seo-premium' AS Slug, 'Marketing SEO-pakket Premium.' AS Omschrijving, '["Onbeperkt zoekwoorden", "4 blogs per maand", "Linkbuilding inbegrepen", "Vaste SEO-specialist"]' AS Kenmerken, 119500 AS Prijs, 'maand' AS Periode, 0 AS Uitgelicht, 4 AS Volgorde
UNION ALL SELECT 'Overig' AS Groep, 'Linkbuilding' AS Dienstsoort, 'Linkbuilding Start' AS Naam, 'linkbuilding-start' AS Slug, 'Linkbuilding-pakket Start.' AS Omschrijving, '["3 backlinks per maand", "Relevante Nederlandse sites", "Maandelijks rapport"]' AS Kenmerken, 14900 AS Prijs, 'maand' AS Periode, 0 AS Uitgelicht, 1 AS Volgorde
UNION ALL SELECT 'Overig' AS Groep, 'Linkbuilding' AS Dienstsoort, 'Linkbuilding Groei' AS Naam, 'linkbuilding-groei' AS Slug, 'Linkbuilding-pakket Groei.' AS Omschrijving, '["7 backlinks per maand", "Gastblogs met eigen content", "Ankertekst-strategie"]' AS Kenmerken, 29900 AS Prijs, 'maand' AS Periode, 1 AS Uitgelicht, 2 AS Volgorde
UNION ALL SELECT 'Overig' AS Groep, 'Linkbuilding' AS Dienstsoort, 'Linkbuilding Pro' AS Naam, 'linkbuilding-pro' AS Slug, 'Linkbuilding-pakket Pro.' AS Omschrijving, '["15 backlinks per maand", "Hoge autoriteit (DA 30+)", "Concurrentieanalyse"]' AS Kenmerken, 54900 AS Prijs, 'maand' AS Periode, 0 AS Uitgelicht, 3 AS Volgorde
UNION ALL SELECT 'Overig' AS Groep, 'Linkbuilding' AS Dienstsoort, 'Linkbuilding Premium' AS Naam, 'linkbuilding-premium' AS Slug, 'Linkbuilding-pakket Premium.' AS Omschrijving, '["30 backlinks per maand", "Premium nieuwssites", "Persberichten", "Vaste specialist"]' AS Kenmerken, 99900 AS Prijs, 'maand' AS Periode, 0 AS Uitgelicht, 4 AS Volgorde
UNION ALL SELECT 'Overig' AS Groep, 'Social Media Onderhoud' AS Dienstsoort, 'Social Start' AS Naam, 'social-start' AS Slug, 'Social Media Onderhoud-pakket Start.' AS Omschrijving, '["1 kanaal", "8 berichten per maand", "Contentkalender"]' AS Kenmerken, 14900 AS Prijs, 'maand' AS Periode, 0 AS Uitgelicht, 1 AS Volgorde
UNION ALL SELECT 'Overig' AS Groep, 'Social Media Onderhoud' AS Dienstsoort, 'Social Groei' AS Naam, 'social-groei' AS Slug, 'Social Media Onderhoud-pakket Groei.' AS Omschrijving, '["2 kanalen", "12 berichten per maand", "Reageren op berichten"]' AS Kenmerken, 29900 AS Prijs, 'maand' AS Periode, 1 AS Uitgelicht, 2 AS Volgorde
UNION ALL SELECT 'Overig' AS Groep, 'Social Media Onderhoud' AS Dienstsoort, 'Social Pro' AS Naam, 'social-pro' AS Slug, 'Social Media Onderhoud-pakket Pro.' AS Omschrijving, '["3 kanalen", "20 berichten per maand", "Advertentiebeheer", "Maandrapport"]' AS Kenmerken, 49900 AS Prijs, 'maand' AS Periode, 0 AS Uitgelicht, 3 AS Volgorde
UNION ALL SELECT 'Overig' AS Groep, 'Social Media Onderhoud' AS Dienstsoort, 'Social Premium' AS Naam, 'social-premium' AS Slug, 'Social Media Onderhoud-pakket Premium.' AS Omschrijving, '["Alle kanalen", "Dagelijkse berichten", "Advertenties en video", "Vaste social media manager"]' AS Kenmerken, 89900 AS Prijs, 'maand' AS Periode, 0 AS Uitgelicht, 4 AS Volgorde
) t
WHERE NOT EXISTS (SELECT 1 FROM Producten p WHERE p.Slug = t.Slug);
